module coexist_checker #(\n    parameter MAX_M = 8,\n    parameter MAX_N = 8,\n    parameter IDX_WIDTH = 3,\n    parameter N_WIDTH = 3\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [N_WIDTH-1:0] m,\n    input wire [N_WIDTH-1:0] n,\n    input wire [IDX_WIDTH-1:0] edge_u_0,\n    input wire [IDX_WIDTH-1:0] edge_u_1,\n    input wire [IDX_WIDTH-1:0] edge_u_2,\n    input wire [IDX_WIDTH-1:0] edge_u_3,\n    input wire [IDX_WIDTH-1:0] edge_u_4,\n    input wire [IDX_WIDTH-1:0] edge_u_5,\n    input wire [IDX_WIDTH-1:0] edge_u_6,\n    input wire [IDX_WIDTH-1:0] edge_u_7,\n    input wire [IDX_WIDTH-1:0] edge_v_0,\n    input wire [IDX_WIDTH-1:0] edge_v_1,\n    input wire [IDX_WIDTH-1:0] edge_v_2,\n    input wire [IDX_WIDTH-1:0] edge_v_3,\n    input wire [IDX_WIDTH-1:0] edge_v_4,\n    input wire [IDX_WIDTH-1:0] edge_v_5,\n    input wire [IDX_WIDTH-1:0] edge_v_6,\n    input wire [IDX_WIDTH-1:0] edge_v_7,\n    output reg done,\n    output reg result\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] CLEAR_COLORS = 3'd1;\n    localparam [2:0] INIT = 3'd2;\n    localparam [2:0] SCAN_PASS = 3'd3;\n    localparam [2:0] CHECK_CHANGED = 3'd4;\n    localparam [2:0] DONE_YES = 3'd5;\n    localparam [2:0] DONE_NO = 3'd6;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [2:0] clear_idx;\n    reg [2:0] pass_counter;\n    reg [2:0] edge_idx;\n    reg changed;\n    reg conflict;\n    reg [2:0] m_reg;\n    reg [2:0] n_reg;\n    reg [1:0] color [0:7];\n\n    // Current edge selection\n    wire [IDX_WIDTH-1:0] current_u;\n    wire [IDX_WIDTH-1:0] current_v;\n    assign current_u = (edge_idx == 0) ? edge_u_0 :\n                       (edge_idx == 1) ? edge_u_1 :\n                       (edge_idx == 2) ? edge_u_2 :\n                       (edge_idx == 3) ? edge_u_3 :\n                       (edge_idx == 4) ? edge_u_4 :\n                       (edge_idx == 5) ? edge_u_5 :\n                       (edge_idx == 6) ? edge_u_6 :\n                       edge_u_7;\n    assign current_v = (edge_idx == 0) ? edge_v_0 :\n                       (edge_idx == 1) ? edge_v_1 :\n                       (edge_idx == 2) ? edge_v_2 :\n                       (edge_idx == 3) ? edge_v_3 :\n                       (edge_idx == 4) ? edge_v_4 :\n                       (edge_idx == 5) ? edge_v_5 :\n                       (edge_idx == 6) ? edge_v_6 :\n                       edge_v_7;\n\n    // Current colors\n    wire [1:0] cu = color[current_u];\n    wire [1:0] cv = color[current_v];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 1'b0;\n            clear_idx <= 3'd0;\n            pass_counter <= 3'd0;\n            edge_idx <= 3'd0;\n            changed <= 1'b0;\n            conflict <= 1'b0;\n            m_reg <= 3'd0;\n            n_reg <= 3'd0;\n            color[0] <= 2'b0;\n            color[1] <= 2'b0;\n            color[2] <= 2'b0;\n            color[3] <= 2'b0;\n            color[4] <= 2'b0;\n            color[5] <= 2'b0;\n            color[6] <= 2'b0;\n            color[7] <= 2'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 1'b0;\n                    if (start) begin\n                        state <= CLEAR_COLORS;\n                        clear_idx <= 3'd0;\n                    end\n                end\n\n                CLEAR_COLORS: begin\n                    if (clear_idx < MAX_M) begin\n                        color[clear_idx] <= 2'b0;\n                        clear_idx <= clear_idx + 3'd1;\n                    end else begin\n                        clear_idx <= 3'd0;\n                        state <= INIT;\n                    end\n                end\n\n                INIT: begin\n                    m_reg <= m;\n                    n_reg <= n;\n                    pass_counter <= 3'd0;\n                    changed <= 1'b0;\n                    conflict <= 1'b0;\n                    edge_idx <= 3'd0;\n                    if (n == 3'd0)\n                        state <= DONE_YES;\n                    else\n                        state <= SCAN_PASS;\n                end\n\n                SCAN_PASS: begin\n                    if (!conflict) begin\n                        if (current_u == current_v) begin\n                            conflict <= 1'b1;\n                        end else if (cu == 2'b0 && cv == 2'b0) begin\n                            color[current_u] <= 2'd1;\n                            color[current_v] <= 2'd2;\n                            changed <= 1'b1;\n                        end else if (cu == 2'b0 && cv != 2'b0) begin\n                            color[current_u] <= (cv == 2'd1) ? 2'd2 : 2'd1;\n                            changed <= 1'b1;\n                        end else if (cv == 2'b0 && cu != 2'b0) begin\n                            color[current_v] <= (cu == 2'd1) ? 2'd2 : 2'd1;\n                            changed <= 1'b1;\n                        end else if (cu == cv) begin\n                            conflict <= 1'b1;\n                        end\n                    end\n\n                    if (edge_idx < n_reg - 3'd1)\n                        edge_idx <= edge_idx + 3'd1;\n                    else begin\n                        state <= CHECK_CHANGED;\n                        edge_idx <= 3'd0;\n                    end\n                end\n\n                CHECK_CHANGED: begin\n                    if (conflict)\n                        state <= DONE_NO;\n                    else if (changed) begin\n                        changed <= 1'b0;\n                        pass_counter <= pass_counter + 3'd1;\n                        if (pass_counter + 3'd1 >= m_reg)\n                            state <= DONE_YES;\n                        else\n                            state <= SCAN_PASS;\n                    end else\n                        state <= DONE_YES;\n                end\n\n                DONE_YES: begin\n                    done <= 1'b1;\n                    result <= 1'b1;\n                end\n\n                DONE_NO: begin\n                    done <= 1'b1;\n                    result <= 1'b0;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule